DO $$ DECLARE v_investment uuid; v_source uuid; BEGIN SELECT id INTO v_investment FROM public.investments WHERE symbol='VCN' LIMIT 1; IF v_investment IS NULL THEN RAISE EXCEPTION 'VCN not found'; END IF; INSERT INTO public.investment_data_sources(investment_id,source_name,source_type,source_url,metric_scope,retrieved_at,source_version,notes) VALUES (v_investment,'Vanguard Canada','official','https://www.vanguard.ca/en/product/etf/equity/9561/vanguard-ftse-canada-all-cap-index-etf','profile,metrics,risk,price,holdings,distributions',now(),'2026-09','Official Vanguard Canada product page; portfolio and risk data as of Jul 31 2026, price data as of Sep 11 2026.') RETURNING id INTO v_source; INSERT INTO public.investment_metrics(investment_id,as_of_date,price,daily_change_pct,yield_pct,distribution_frequency,mer_pct,aum,shares_outstanding) VALUES (v_investment,'2026-09-11',72.77,0.58,2.04,'quarterly',0.05,17.75e9,240311900); INSERT INTO public.investment_risk_metrics(investment_id,as_of_date,risk_level,standard_deviation_pct,beta,sharpe_ratio) VALUES (v_investment,'2026-07-31','Medium to High',10.71,1.00,1.68); INSERT INTO public.investment_price_history(investment_id,price_date,nav,close_price,currency,source_id) VALUES (v_investment,'2026-09-11',72.7683,72.78,'CAD',v_source),(v_investment,'2026-09-10',72.3495,72.30,'CAD',v_source),(v_investment,'2026-09-09',73.1546,73.15,'CAD',v_source),(v_investment,'2026-09-08',73.5982,73.60,'CAD',v_source),(v_investment,'2026-09-04',74.4040,74.39,'CAD',v_source),(v_investment,'2026-09-03',74.6427,74.64,'CAD',v_source),(v_investment,'2026-09-02',73.5366,73.47,'CAD',v_source),(v_investment,'2026-09-01',72.9881,72.97,'CAD',v_source),(v_investment,'2026-08-31',73.8806,73.84,'CAD',v_source),(v_investment,'2026-08-28',74.4519,74.43,'CAD',v_source); INSERT INTO public.investment_holdings(investment_id,as_of_date,holding_symbol,holding_name,country_code,sector,asset_type,weight_pct,source_id) VALUES (v_investment,'2026-07-31','RY','Royal B